package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaElDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Ακούγοντας έναν κόκορα ή έναν γάιδαρο", "Ω Αλλάχ, Σου ζητώ τη γενναιοδωρία Σου (πετεινός). — Αναζητώ καταφύγιο στον Αλλάχ από τον Σαϊτάν, τον καταραμένο (γάιδαρο).", "Ακούγοντας έναν κόκορα να ζητά τη γενναιοδωρία του Αλλάχ. στο άκουσμα ενός γάιδαρου να ψάχνει καταφύγιο από τον Σαϊτάν.", "Ο πετεινός βλέπει έναν άγγελο και ο γάιδαρος έναν διάβολο."),
        "dua_something_liked" to DuaText("Βλέποντας κάτι αξιοθαύμαστο (Against Evil Eye)", "Αυτό που ο Αλλάχ θέλει. Ω Αλλάχ, ευλόγησέ το.", "Όταν βλέπετε κάτι αξιοθαύμαστο να ανήκει σε κάποιον, προσευχηθείτε για ευλογία.", "Η προσευχή για ευλογία αποτρέπει το κακό μάτι."),
        "dua_sell_buy_debt_repaid" to DuaText("Κατά την αποπληρωμή ενός χρέους", "Είθε ο Αλλάχ να σας ευλογεί στην οικογένειά σας και στον πλούτο σας.", "Για τον δανειστή κατά την εξόφληση ενός χρέους.", "Η επιστροφή για ένα δάνειο είναι χάρη και αποπληρωμή."),
        "dua_talbiyah" to DuaText("Talbiyah", "Εδώ είμαι, ω Αλλάχ, εδώ είμαι. Εδώ είμαι, δεν έχεις σύντροφο, εδώ είμαι. Σίγουρα όλοι οι έπαινοι, οι ευλογίες και η κυριαρχία είναι δικές σας. Δεν έχεις σύντροφο.", "Δυνατά μετά την είσοδο στο Ιχράμ.", "Το έμβλημα του Χατζ και της Ούμρα."),
        "dua_yamani_hajar" to DuaText("Μεταξύ Rukn Yamani και Hajar Aswad", "Κύριε μας, δώσε μας καλό στον κόσμο αυτό και καλό στο επέκεινα, και φύλαξέ μας από την τιμωρία της φωτιάς.", "Σε ταβάφ, ανάμεσα στη Γωνιά της Υεμένης και τη Μαύρη Πέτρα.", "Ο Προφήτης ﷺ το απήγγειλε αυτό σε αυτό το μέρος στο ταβάφ."),
        "dua_safa_marwa" to DuaText("Σε Safa και Marwah", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος, και έχει δύναμη πάνω σε όλα τα πράγματα. Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό. Εκπλήρωσε την υπόσχεσή Του, βοήθησε τον δούλο Του και μόνος νίκησε τους συνασπισμένους εχθρούς.", "Αναρρίχηση στη Σάφα και στραμμένη προς την Κιμπλά (τρεις φορές).", "Το dhikr του Προφήτη ﷺ στη Safa και στη Marwah."),
        "dua_arafah" to DuaText("Το καλύτερο Dua της Ημέρας της Arafah", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος, και έχει δύναμη πάνω σε όλα τα πράγματα.", "Η Ημέρα της Αραφά - η καλύτερη ντουέτα.", "Η καλύτερη ντουά είναι η ντουά της Ημέρας της Αράφα, και τα καλύτερα λόγια είναι αυτά."),
        "dua_takbeer_tashreeq" to DuaText("Takbeer-e-Tashreeq", "Ο Αλλάχ είναι ο Μεγαλύτερος, ο Αλλάχ είναι ο Μεγαλύτερος. Δεν υπάρχει θεός εκτός από τον Αλλάχ. Ο Αλλάχ είναι ο Μεγαλύτερος, ο Αλλάχ είναι ο Μεγαλύτερος και όλος ο έπαινος είναι για τον Αλλάχ.", "Μετά από κάθε υποχρεωτική προσευχή από το Fajr της 9ης Dhul-Hijjah έως το Asr της 13 Dhul-Hijjah.", "Αναφέρεται από τον Ali και τον Ibn Mas'ud (RA) — wajib σύμφωνα με τους Hanafis."),
        "dua_zamzam" to DuaText("Πίνοντας Zamzam", "Ω Αλλάχ, Σου ζητώ ωφέλιμη γνώση, άφθονη προμήθεια και θεραπεία από κάθε ασθένεια.", "Όταν πίνετε Zamzam, κάντε ντουά για ό,τι σκοπεύετε.", "Το Zamzam είναι για ό,τι πίνεται (Ibn Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Αναστοχασμός στη Δημιουργία", "Κύριε μας, δεν τα δημιούργησες όλα αυτά μάταια. Δόξα σε σένα, φύλαξέ μας λοιπόν από την τιμωρία της Φωτιάς.", "Η δόξα εκείνων που στοχάζονται για τη δημιουργία των ουρανών και της γης.", "Η ντουά των ανθρώπων με κατανόηση (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Ακούσαμε τον Καλούντα στην Πίστη", "Κύριε μας, ακούσαμε έναν καλούντα να καλεί στην πίστη, λέγοντας «Πίστεψε στον Κύριό σου», και πιστέψαμε. Κύριε μας, συγχώρεσε μας τις αμαρτίες μας, διώξε από εμάς τις κακοτοπιές μας και κάνε μας να πεθάνουμε μαζί με τους δίκαιους.", "Μια ντουέτα για την πίστη και τον θάνατο μεταξύ των δικαίων.", "Μια ντουά για συγχώρεση και καλό τέλος."),
        "dua_q_atina_ma_waadtana" to DuaText("Δώστε μας αυτό που υποσχεθήκατε", "Κύριε μας, χάρισέ μας αυτό που μας υποσχέθηκες μέσω των Αγγελιαφόρων Σου και μη μας ντροπιάζεις την ημέρα της Ανάστασης. Πράγματι, δεν παραβαίνετε την υπόσχεσή Σου.", "Καταφύγιο από την ντροπή την ημέρα της Ανάστασης.", "Αναζητώντας την τιμή στο επέκεινα."),
        "dua_q_israfana" to DuaText("Συγχωρήστε τις υπερβολές μας", "Κύριε μας, συγχώρεσέ μας τις αμαρτίες μας και τις υπερβολές μας στις υποθέσεις μας, κάνε τα πόδια μας σταθερά και βοήθησέ μας ενάντια στους απίστους.", "Η ντουέτα των συντρόφων των προγενέστερων Προφητών.", "Μια ντουέτα για σταθερότητα και συγχώρεση."),
        "dua_q_jamiun_nas" to DuaText("Θα Μαζέψεις την Ανθρωπότητα", "Κύριε μας, σίγουρα θα συγκεντρώσεις τους ανθρώπους μια Ημέρα για την οποία δεν υπάρχει αμφιβολία. Πράγματι, ο Αλλάχ δεν παραβαίνει την υπόσχεσή Του.", "Επιβεβαίωση της βεβαιότητας στην Ημέρα της Ανάστασης.", "Η ντουά των εδραιωμένων στη γνώση."),
        "dua_q_maash_shahidin" to DuaText("Γράψτε μας ανάμεσα στους Μάρτυρες", "Κύριε μας, πιστέψαμε, γράψτε μας λοιπόν ανάμεσα στους μάρτυρες.", "Η ντουέτα εκείνων που αναγνώρισαν την αλήθεια και πίστεψαν.", "Μια ντουέτα για την αποδοχή της πίστης κάποιου."),
        "dua_q_la_tajalna_zalimin" to DuaText("Όχι με τους αδικημένους", "Κύριέ μας, μη μας βάζεις με τους αδικημένους ανθρώπους.", "Η ντουέτα των ανθρώπων του αλ-Αραφ.", "Καταφύγιο από τη μοίρα των αδίκων."),
        "dua_q_tawaffana_muslimin" to DuaText("Υπομονή και Θάνατος ως Μουσουλμάνοι", "Κύριε μας, δώσε μας υπομονή και κάνε μας να πεθάνουμε ως Μουσουλμάνοι.", "Η ντουά των μάγων του Φαραώ όταν πίστεψαν.", "Υπομονή στη δοκιμασία και τέλος στην πίστη."),
        "dua_q_la_tajalna_fitnah" to DuaText("Όχι Δίκη για τους Καταπιεστές", "Στον Αλλάχ βασιζόμαστε. Κύριε μας, μη μας κάνεις δοκιμασία για τους αδικημένους ανθρώπους και σώσε μας με το έλεός Σου από τους άπιστους.", "Η δούα των ανθρώπων της Μούσας (AS).", "Μια ντουέτα για τη διάσωση από την καταπίεση και τους καταπιεστές."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Dua του Nuh (AS) για Συγχώρεση", "Κύριε μου, ζητώ καταφύγιο σε Σένα για να μην σου ζητήσω κάτι για το οποίο δεν γνωρίζω. Και αν δεν με συγχωρήσεις και δεν με ελεήσεις, θα είμαι ανάμεσα στους ηττημένους.", "Η ντουέτα της μετάνοιας του Προφήτη Νουχ (AS).", "Ένα μάθημα να ρωτάς με σωστούς τρόπους."),
        "dua_q_mudkhala_sidq" to DuaText("Είσοδος και Έξοδος της Αλήθειας", "Κύριε μου, κάνε με να μπω με την αλήθεια και να βγω με την αλήθεια, και δώσε μου από τον εαυτό σου μια εξουσία υποστήριξης.", "Πριν εισαγάγετε μια νέα εργασία, σπίτι ή μέρος.", "Η ντουά δίδαξε στον Προφήτη το ﷺ την εποχή του Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Dua of Zakariya (AS) — Μην με αφήνεις μόνο", "Κύριε μου, μη με αφήνεις μόνη, και εσύ είσαι ο καλύτερος κληρονόμος.", "Για όσους αναζητούν παιδιά.", "Μέσω αυτής της ντουά, ο Αλλάχ χορήγησε στον Yahya το (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Ευλογημένος τόπος προσγείωσης", "Κύριε μου, άφησέ με να προσγειωθώ σε ένα ευλογημένο σημείο απόβασης, και εσύ είσαι ο καλύτερος από αυτούς που φέρνουν στη στεριά.", "Όταν μετακομίζετε σε ένα νέο σπίτι ή σταματάτε κάπου - η ντουά του Nuh (AS).", "Μια ντουά για ευλογία σε ένα νέο μέρος."),
        "dua_q_amanna_faghfir" to DuaText("Πιστεύουμε, οπότε συγχωρέστε μας", "Κύριε μας, πιστέψαμε, συγχώρεσέ μας και ελέησέ μας, και εσύ είσαι ο καλύτερος των ελεήμων.", "Η ντουέτα των δικαίων υπηρετών του Αλλάχ.", "Μια περιεκτική ντουά για συγχώρεση και έλεος."),
        "dua_q_isrif_jahannam" to DuaText("Αποτρέψτε την Τιμωρία της Κόλασης", "Κύριε μας, αποτρέψε από εμάς την τιμωρία της κόλασης. πράγματι η τιμωρία του είναι διαρκής. Πράγματι, είναι κακός οικισμός και κατοικία.", "Η ντουά των υπηρετών του Ελεήμονος ('Ibad ar-Rahman).", "Μια κορανική ντουέτα για καταφύγιο από την κόλαση."),
        "dua_q_hab_li_hukman" to DuaText("Dua of Ibrahim (AS) — Σοφία και Τζάννα", "Κύριε μου, δώσε μου σοφία και ένωσε με με τους δίκαιους, δώσε μου μια τιμητική μνεία μεταξύ των μεταγενέστερων γενεών και κάνε με μεταξύ των κληρονόμων του Κήπου της Ευδαιμονίας.", "Ζητώντας τη σοφία, τη συντροφιά των δικαίων και τον Παράδεισο.", "Μια περιεκτική ντουέτα του Ιμπραήμ (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Δέηση του Λουτ (AS) — Σώσε την οικογένειά μου", "Κύριε μου, σώσε εμένα και την οικογένειά μου από (τη συνέπεια) αυτού που κάνουν.", "Προστασία της οικογένειάς του από ένα περιβάλλον κακού.", "Προστασία της οικογένειας από το κακό."),
        "dua_q_sulaiman_awzini" to DuaText("Δόξα του Σουλεϊμάν (AS) για Ευγνωμοσύνη", "Κύριε μου, επέτρεψέ με να είμαι ευγνώμων για την εύνοιά Σου που χάρισες σε μένα και στους γονείς μου, και να κάνω ορθές πράξεις που Σε ευχαριστούν, και δέξου με με το έλεός Σου ανάμεσα στους δίκαιους υπηρέτες Σου.", "Για την ικανότητα να είσαι ευγνώμων για τις ευλογίες.", "Η δόξα της ευγνωμοσύνης του Σουλεϊμάν (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Dua of Musa (AS) — Αδίκησα τον εαυτό μου", "Κύριε μου, αδίκησα τον εαυτό μου, γι' αυτό συγχώρεσέ με.", "Άμεση μετάνοια μετά από λάθος.", "Ο Αλλάχ συγχώρεσε τον Μούσα (AS)."),
        "dua_q_musa_najjini" to DuaText("Dua of Musa (AS) — Σώσε με από καταπιεστές", "Κύριε μου, σώσε με από τους αδικημένους ανθρώπους.", "Όταν φοβάται τους καταπιεστές.", "Η ντουά του Μούσα (AS) κατά την αναχώρηση από την Αίγυπτο."),
        "dua_q_lut_unsurni" to DuaText("Dua of Lut (AS) — Βοήθεια κατά των διαφθορέων", "Κύριε μου, βοήθησέ με ενάντια στους διεφθαρμένους ανθρώπους.", "Για βοήθεια ενάντια σε αυτούς που διαδίδουν τη διαφθορά.", "Η ντουά όσων στέκονται σταθερά στην αλήθεια."),
        "dua_q_hab_li_salihin" to DuaText("Dua του Ibrahim (AS) για ένα δίκαιο παιδί", "Κύριε μου, χάρισε μου (ένα παιδί) από τους δίκους.", "Ζητώντας δίκαια παιδιά.", "Μέσω αυτής της dua Isma'il χορηγήθηκε (AS)."),
        "dua_q_wasita_kulla_shay" to DuaText("Δέηση των αγγέλων που φέρουν τον Θρόνο", "Κύριε μας, τα περικλείεις όλα σε έλεος και γνώση, γι' αυτό συγχώρησε αυτούς που μετανοούν και ακολουθούν τον δρόμο Σου και προστάτευσέ τους από την τιμωρία της κόλασης.", "Οι άγγελοι που φέρουν τον Θρόνο κάνουν αυτή τη ντουά για τους πιστούς.", "Απαγγέλθηκε με την πρόθεση να συμπεριληφθεί στη ντουέτα των αγγέλων."),
        "dua_q_ikhwanina" to DuaText("Για τα αδέρφια μας που προηγήθηκαν", "Κύριε μας, συγχώρεσε εμάς και τους αδελφούς μας που προηγήθηκαν στην πίστη μας, και μην βάλεις μνησικακία στις καρδιές μας απέναντι σε αυτούς που πιστεύουν. Κύριε μας, είσαι πράγματι Καλός και Ελεήμων.", "Μια ντουά για τους πιστούς που ήρθαν πριν και για μια καθαρή καρδιά.", "Μια ντουέτα για τους ευγενείς συντρόφους (RA) και τους προηγούμενους πιστούς."),
        "dua_q_alayka_tawakkalna" to DuaText("Σε Σένα Βασιζόμαστε (Ibrahim AS)", "Κύριε μας, σε Σένα στηριζόμαστε, σε Σένα στρεφόμαστε και σε Σένα είναι η επιστροφή. Κύριε μας, μη μας κάνεις δοκιμασία για τους άπιστους και συγχώρεσέ μας. Κύριε μας, είσαι πράγματι ο Παντοδύναμος, ο Σοφός.", "Η ντουέτα του Ιμπραήμ (AS) και των συντρόφων του.", "Μια ντουέτα εμπιστοσύνης στον Αλλάχ και στροφή προς Αυτόν."),
        "dua_q_atmim_nurana" to DuaText("Τελειοποιήστε το φως μας", "Κύριε μας, τελειοποίησε για μας το φως μας και συγχώρεσέ μας. Πράγματι, έχεις δύναμη πάνω σε όλα τα πράγματα.", "Η δόξα των πιστών την ημέρα της Ανάστασης.", "Ζητώντας φως στο Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua of Asiya — Ένα σπίτι στο Jannah", "Κύριέ μου, χτίστε μου κοντά Σου ένα σπίτι στον Παράδεισο, σώσε με από τον Φαραώ και τις πράξεις του και σώσε με από τους αδικημένους ανθρώπους.", "Η ντουά της Asiya, της συζύγου του Φαραώ.", "Ο Αλλάχ την έκανε παράδειγμα για τους πιστούς."),
        "dua_adhan_response" to DuaText("Απαντώντας στο Adhan", "Δεν υπάρχει δύναμη και δύναμη εκτός από τον Αλλάχ.", "Επαναλάβετε αυτό που λέει ο μουεζίνης. στο 'Hayya 'alas-salah' και 'Hayya 'alal-falah' το λένε αυτό.", "Όποιος ανταποκριθεί από καρδιάς θα μπει στον Παράδεισο."),
        "dua_adhan_shahadah" to DuaText("Μετά το Shahadah του Muazzin", "Και εγώ επίσης καταθέτω μαρτυρία ότι κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο, και ότι ο Μωάμεθ ﷺ είναι υπηρέτης και αγγελιοφόρος Του. Είμαι ευχαριστημένος με τον Αλλάχ ως Κύριο, με τον Μωάμεθ ﷺ ως Αγγελιοφόρο και με το Ισλάμ ως θρησκεία.", "Στο άκουσμα της μαρτυρίας της πίστης του μουεζίνη.", "Οι αμαρτίες του συγχωρούνται."),
        "dua_istiftah_baid" to DuaText("Εναρκτήρια δέηση: Απομάκρυνέ με από τις αμαρτίες", "Ω Αλλάχ, απομάκρυνέ με από τις αμαρτίες μου όπως έχεις απομακρύνει την ανατολή από τη δύση. Ω Αλλάχ, καθάρισε με από τις αμαρτίες όπως καθαρίζεται ένα λευκό ρούχο από τη βρωμιά. Ω Αλλάχ, ξέπλυνε τις αμαρτίες μου με νερό, χιόνι και χαλάζι.", "Μετά το εναρκτήριο takbir (μπορεί επίσης να ειπωθεί στη θέση του Sana).", "Ο Προφήτης ﷺ το απήγγειλε μεταξύ του τακμπίρ και της απαγγελίας."),
        "dua_hamdan_kathiran" to DuaText("Άφθονος έπαινος μετά το Ρούκου", "Κύριε μας, σε Σένα ανήκει ο έπαινος — άφθονος, αγνός και ευλογημένος έπαινος.", "Αφού σηκώθηκε από το ρούκου, μαζί με το 'Rabbana lakal-hamd'.", "Περισσότεροι από τριάντα άγγελοι έτρεχαν για να το καταγράψουν πρώτοι."),
    )
}
